// Extract customer and purchase data from Stripe webhook
const event = $input.first().json.body;
const session = event.data.object;

const customerEmail = session.customer_details?.email || session.customer_email || '';
const customerName = session.customer_details?.name || '';
const firstName = customerName.split(' ')[0] || '';
const lastName = customerName.split(' ').slice(1).join(' ') || '';
const amountTotal = (session.amount_total / 100).toFixed(2);
const currency = (session.currency || 'usd').toUpperCase();
const paymentStatus = session.payment_status || '';
const stripeCustomerId = session.customer || '';
const sessionId = session.id || '';
const phone = session.customer_details?.phone || '';

// Determine product from metadata or line items
const product = session.metadata?.product || 'Direct Shippers List';

return [{
  json: {
    customerEmail,
    customerName,
    firstName,
    lastName,
    amountTotal,
    currency,
    paymentStatus,
    stripeCustomerId,
    sessionId,
    phone,
    purchaseDate: new Date().toISOString(),
    product
  }
}];

